/**
 * Component: Interactive Pricing Cards
 * Author: @Shadad-01 (https://tailwindflex.com/@Shadad-01)
 * Source: https://tailwindflex.com/@Shadad-01/interactive-pricing-cards
 * Attribution: Créé par @Shadad-01 sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function InteractivePricingCards() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Interactive Pricing Cards</title>
    <style>
        :root {
            --primary: #4a6bff;
            --secondary: #f8f9fa;
            --text: #333;
            --light-text: #777;
            --shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            --popular-accent: #ff6b6b;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f5f7ff;
            color: var(--text);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
            margin: 0;
        }

        .pricing-container {
            display: flex;
            gap: 25px;
            max-width: 1000px;
            width: 100%;
        }

        .pricing-card {
            background: white;
            border-radius: 10px;
            padding: 30px;
            box-shadow: var(--shadow);
            transition: all 0.3s ease;
            flex: 1;
            position: relative;
            overflow: hidden;
        }

        .pricing-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
        }

        .pricing-card.popular {
            border: 2px solid var(--primary);
        }

        .popular-badge {
            position: absolute;
            top: 0;
            right: 0;
            background: var(--popular-accent);
            color: white;
            padding: 5px 15px;
            font-size: 12px;
            font-weight: bold;
            border-bottom-left-radius: 10px;
        }

        .plan-name {
            font-size: 22px;
            font-weight: 600;
            margin-bottom: 10px;
        }

        .plan-price {
            font-size: 36px;
            font-weight: 700;
            margin: 20px 0;
        }

        .plan-price span {
            font-size: 16px;
            font-weight: normal;
            color: var(--light-text);
        }

        .plan-features {
            list-style: none;
            padding: 0;
            margin: 25px 0;
        }

        .plan-features li {
            padding: 8px 0;
            border-bottom: 1px solid #eee;
            color: var(--light-text);
        }

        .plan-features li:last-child {
            border-bottom: none;
        }

        .plan-features li::before {
            content: "✓";
            color: var(--primary);
            font-weight: bold;
            margin-right: 10px;
        }

        .cta-button {
            width: 100%;
            padding: 12px;
            border: none;
            border-radius: 5px;
            background: var(--primary);
            color: white;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .cta-button:hover {
            background: #3a5bef;
            transform: translateY(-2px);
        }

        .popular .cta-button {
            background: var(--popular-accent);
        }

        .popular .cta-button:hover {
            background: #e05a5a;
        }

        @media (max-width: 768px) {
            .pricing-container {
                flex-direction: column;
            }
        }
    </style>
</head>
<body>
    <div class="pricing-container">
        <!-- Basic Plan -->
        <div class="pricing-card">
            <h3 class="plan-name">Basic</h3>
            <div class="plan-price">$9<span>/month</span></div>
            <ul class="plan-features">
                <li>10 Projects</li>
                <li>5 GB Storage</li>
                <li>Basic Support</li>
                <li>Email Reports</li>
            </ul>
            <button class="cta-button">Get Started</button>
        </div>

        <!-- Popular Plan -->
        <div class="pricing-card popular">
            <div class="popular-badge">Popular</div>
            <h3 class="plan-name">Professional</h3>
            <div class="plan-price">$19<span>/month</span></div>
            <ul class="plan-features">
                <li>Unlimited Projects</li>
                <li>50 GB Storage</li>
                <li>Priority Support</li>
                <li>Advanced Analytics</li>
                <li>Weekly Reports</li>
            </ul>
            <button class="cta-button">Get Started</button>
        </div>

        <!-- Enterprise Plan -->
        <div class="pricing-card">
            <h3 class="plan-name">Enterprise</h3>
            <div class="plan-price">$49<span>/month</span></div>
            <ul class="plan-features">
                <li>Unlimited Projects</li>
                <li>500 GB Storage</li>
                <li>24/7 Support</li>
                <li>Advanced Analytics</li>
                <li>Dedicated Account Manager</li>
                <li>Custom Reports</li>
            </ul>
            <button class="cta-button">Get Started</button>
        </div>
    </div>
</body>
</html>" }} />
  );
}
